              "timeFrame": "1-4 weeks"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Comparison of IL-10 levels between standard and aggressive therapy treatments",
              "description": "To determine whether or not patients who have high IL-10 levels treated with aggressive antibiotic therapy have better outcomes compared with standard therapy.",
              "timeFrame": "About 2 months from blood draw to the batch results"
            }
          ]
