        "descriptionModule": {
          "briefSummary": "To assess antimicrobial resistance rates and minimal inhibitory concentrations in H. pylori isolated from patients with upper gastrointestinal disease with long-term period.",
          "detailedDescription": "Failure of eradication treatment against Helicobacter pylori (H. pylori) is mainly caused by antimicrobial resistance. However, there is no relevant studies have been conducted on the prevalence and trend of antimicrobial resistance, which is considered to have a major determinant of eradication failure. In addition, studying the trend of resistance rate is an important basis for establishing an appropriate strategy for eradication treatment in the future.\n\nPatients who had H. pylori colonies isolated from culture were consecutively enrolled from 2003. From each patient, 1 to 10 H. pylori isolates were isolated. Trends in MIC distribution and prevalence of resistance were investigated for each antimicrobial agent according to time period. Antimicrobi resistances suspected to related with failure of empirical PPI triple, quadruple, and rescue fluoroquinolone-containing treatment were also investigated. Multiple resistance, which is simultaneously resistant to various antibiotics, will also be investigated. Risk factors for the antibiotic resistance will be analyzed."
        },
        "conditionsModule": {
          "conditions": [
            "Helicobacter Pylori Infection",
            "Helicobacter Pylori Associated Gastrointestinal Disease",
            "Helicobacter Pylori Infection, Susceptibility to",
            "Helicobacter Pylori 23S rRNA Clarithromycin Resistance Mutation"
          ],
          "keywords": [
            "eradication",
            "rescue therapy",
            "antibiotics",
            "resistance",
            "Helicobacter pylori"
          ]
        },
        "designModule": {
          "studyType": "OBSERVATIONAL",
          "patientRegistry": false,
          "designInfo": {
            "observationalModel": "CASE_ONLY",
            "timePerspective": "PROSPECTIVE"
          },
          "bioSpec": {
            "retention": "SAMPLES_WITH_DNA",
            "description": "H. pylori strains isolated by study subjects.\n\nSusceptibility is investigated for each of the H. pylori strains, and mutations (e.g., 23SrRNA, gyrA, etc.) that can decisively cause resistance can be investigated only if necessary. All consent to these biosamples will be obtained in advance."
          },
          "enrollmentInfo": {
            "count": 2000,
            "type": "ESTIMATED"
          }
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Resistance rate",
              "description": "It means resistance to an antimicrobial agent applicable for H. pylori eradication. Minimal inhibitory concentration test was performed for amoxicillin, clarithromycin, metronidazole, tetracycline, rifabutin, levofloxacin, and moxifloxacin using agar dilution method.",
              "timeFrame": "through study completion, an average of 1 year"
            },
            {
              "measure": "Minimal inhibitory concentration (MIC) distribution",
              "description": "The concentration of specific antibiotics that can kill 50% of H. pylori is defined as MIC50. Each analyzes the ratio of strain according to the concentration of antibiotics.",
              "timeFrame": "through study completion, an average of 1 year"
            },
            {
              "measure": "Multiple resistance, prevalance and trends",
              "description": "It is defined as the case where the H. pylori strain shows resistance to several antimicrobial agents at the same time. Multiple resistance is calculated by calculating the proportion of strains with simultaneous resistance to 1\\> clarithromycin and metronidazole, 2\\> clarithromycin and fluoroquinolone, and 3\\> clarithromycin, fluoroquinolone, and metronidazole.",
              "timeFrame": "through study completion, an average of 1 year"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Risk factor for eradication failure or success",
              "description": "Risk factors for eradication failure or success could be found in the demographic profile of the study subject along with resistance/non-resistance to each antibiotic to H. pylori and its strain.\n\nAccording to previous studies, risk factors related with eradication failure or success are usually known from demographic data such as age, sex, and history of eradication treatment. In our study, we use logistic regression analysis to find out whether these factors have significance.",
              "timeFrame": "through study completion, an average of 1 year"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Subjects who had a H. pylori infection and had consented to undergo culture analysis via endoscopic resection, in order to determine the minimal inhibitory concentration (MIC) of various antibiotics.\n\nExclusion Criteria:\n\n* Patients with a concurrent critical illness, who abused drugs or alcohol, who were pregnant or nursing, or those who had received antibiotics, PPIs, or bismuth salts within 4 weeks, were excluded.",
          "healthyVolunteers": false,
          "sex": "ALL",
          "stdAges": [
            "CHILD",
            "ADULT",
            "OLDER_ADULT"
          ],
          "studyPopulation": "The subjects of this study all had H. pylori infection. None of them should meet the exclusion criteria. Even though successfully proven H. pylori infection, culture procedures must be successful and the susceptibility must be clearly determined by obtaining MIC values to be finally included in this study. According to the literature, culture is successful at approximately 2/3. Informed consent will be obtained from all study subjects.",
          "samplingMethod": "NON_PROBABILITY_SAMPLE"
        },
