          "secondaryOutcomes": [
            {
              "measure": "Outcome Renal Scarring",
              "description": "Renal scarring was defined as a decreased uptake of tracer that was associated with loss of contours or the presence of cortical thinning. Outcome dimercaptosuccinic acid (DMSA) scan was performed at 2 years after enrollment or 3-4 months after the child had met treatment failure criteria.",
              "timeFrame": "2 years"
            },
            {
              "measure": "Severe Renal Scarring on Outcome Scan",
              "description": "Severe renal scarring was defined as scarring in more than 4 of 12 segments in at least one kidney or global atrophy characterized by diffusely scarred and shrunken kidney. Outcome DMSA scan performed at 2 years after enrollment or 3-4 months after the child had met treatment failure criteria.",
              "timeFrame": "2 years"
            },
            {
              "measure": "New Renal Scarring on Outcome Scan",
              "description": "New renal scarring was defined as scarring on the outcome renal scan with technetium -99m-labeled dimercaptosuccinic acid that was not present at baseline. Outcome DMSA scan performed at 2 years after enrollment or 3-4 months after the child had met treatment failure criteria.",
              "timeFrame": "2 years"
            },
            {
              "measure": "Treatment Failure Composite",
              "description": "Treatment failure was defined as the occurrence of two febrile urinary tract infections (UTIs), one febrile UTI and three symptomatic UTIs, four symptomatic UTIs, or new or worsening renal scarring on an interim scan (e.g,, the 12-month visit); renal scans from the 2-year visit are NOT considered in the treatment failure criteria.",
